#include <stdio.h>

long long factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

int fibonacci(int n) {
    if (n <= 1) return n;
    return fibonacci(n-1) + fibonacci(n-2);
}

int main() {
    int n;
    printf("Enter n: ");
    scanf("%d", &n);
    printf("Factorial(%d) = %lld\n", n, factorial(n));
    printf("Fibonacci(%d) = %d\n", n, fibonacci(n));
    return 0;
}

